#!/usr/bin/env python3
"""Build the Neon Keygen tune."""
import json, subprocess, sys
import numpy as np, base64, os

def note_name_to_num(name):
    notes={'C':0,'C#':1,'D':2,'D#':3,'E':4,'F':5,'F#':6,'G':7,'G#':8,'A':9,'A#':10,'B':11}
    idx=0
    n=notes[name[idx]]; idx+=1
    if name[idx]=='#': n+=1; idx+=1
    if name[idx]=='-': idx+=1
    octave=int(name[idx:])
    return 1+12*octave+n

def call(tool, args):
    r = subprocess.run(['ft2','call',tool,json.dumps(args)], capture_output=True, text=True)
    return json.loads(r.stdout)['content'][0]['text']

# Instruments
KICK, SNARE, HAT, OPENHAT, CLAP = 1,2,3,4,5
BASS, LEAD, PAD, ARP, STAB = 6,7,8,9,10
CH_KICK, CH_SN, CH_HAT, CH_BASS, CH_LEAD, CH_PAD, CH_ARP, CH_STAB = 0,1,2,3,4,5,6,7

BPM = 140
SPEED = 3
PATTERN_ROWS = 64   # 4 bars per pattern (16 rows/bar)

# Mix levels (volume column values 0-64)
VOL = {
    'kick': 52, 'snare': 46, 'clap': 40, 'hat': 34, 'openhat': 38,
    'bass': 44, 'lead': 50, 'pad': 30, 'arp': 36, 'stab': 34,
}

# Harmony - A minor
CHORD_SEQUENCE = [
    'Am','Am','F','F', 'C','C','G','G',
    'Am','Am','F','F', 'C','C','G','G',
    'Am','Am','F','F', 'C','C','G','G',
    'Am','Am','F','F', 'C','C','E','E',
    'Am','Am','F','F', 'C','C','G','G',
    'Am','Am','F','F', 'C','C','E','E',
]
CHORDS = {
    'Am': {'root':'A','bass':'A','notes':['A','C','E'],'octave':3},
    'F':  {'root':'F','bass':'F','notes':['F','A','C'],'octave':3},
    'C':  {'root':'C','notes':['C','E','G'],'octave':4},
    'G':  {'root':'G','notes':['G','B','D'],'octave':3},
    'E':  {'root':'E','notes':['E','G#','B'],'octave':3},
}

def chord_for_bar(bar_idx):
    return CHORD_SEQUENCE[bar_idx % len(CHORD_SEQUENCE)]

NOTE_OFF = 97

def set_cell(pat, row, ch, note=None, inst=None, vol=None, fx=None, fxp=None):
    args = {'pattern':pat, 'row':row, 'channel':ch}
    if note is not None: args['note'] = note
    if inst is not None: args['instrument'] = inst
    if vol is not None: args['volume'] = vol
    if fx is not None: args['effect'] = fx
    if fxp is not None: args['effect_param'] = fxp
    call('pattern_set_cell', args)

def note_off(pat, row, ch):
    call('pattern_set_cell', {'pattern':pat,'row':row,'channel':ch,'note':97})

def clear_pattern(pat):
    call('pattern_clear', {'pattern':pat})

def set_pattern_length(pat, rows):
    call('pattern_set_length', {'pattern':pat, 'rows':rows})

# ============================================================
# DRUMS
# ============================================================
def place_drums(pat, start_bar, num_bars, kick='four', hat='16th', snare=True, gbar_offset=0):
    for b in range(num_bars):
        base = (start_bar+b)*16
        if kick == 'four':
            for beat in range(4):
                set_cell(pat, base+beat*4, CH_KICK, note='C-3', inst=KICK, vol=VOL['kick'])
        elif kick == 'syncopated':
            set_cell(pat, base+0, CH_KICK, note='C-3', inst=KICK, vol=VOL['kick'])
            set_cell(pat, base+6, CH_KICK, note='C-3', inst=KICK, vol=VOL['kick']-8)
            set_cell(pat, base+10, CH_KICK, note='C-3', inst=KICK, vol=VOL['kick']-4)
            set_cell(pat, base+12, CH_KICK, note='C-3', inst=KICK, vol=VOL['kick'])
        if snare:
            set_cell(pat, base+4, CH_SN, note='C-3', inst=SNARE, vol=VOL['snare'])
            set_cell(pat, base+12, CH_SN, note='C-3', inst=CLAP, vol=VOL['clap'])
        if hat == '16th':
            for i in range(16):
                vol = VOL['hat'] if i%2==0 else VOL['hat']-8
                inst = HAT
                if i == 14:
                    inst = OPENHAT; vol = VOL['openhat']
                set_cell(pat, base+i, CH_HAT, note='C-3', inst=inst, vol=vol)
        elif hat == '8th':
            for i in range(0,16,2):
                set_cell(pat, base+i, CH_HAT, note='C-3', inst=HAT, vol=VOL['hat'])
        elif hat == 'offbeat':
            for i in range(2,16,4):
                set_cell(pat, base+i, CH_HAT, note='C-3', inst=HAT, vol=VOL['hat'])
                set_cell(pat, base+i+2, CH_HAT, note='C-3', inst=OPENHAT, vol=VOL['openhat']-4)

