        bar = start_bar+b
        gbar = gbar_offset+b
        chord = chord_for_bar(gbar)
        root = CHORDS[chord].get('bass', CHORDS[chord]['root'])
        base = bar*16
        bn = f'{root}-2'
        bn3 = f'{root}-3'
        if style == 'driving16':
            for i in range(16):
                if i%4==0: n, v = bn, VOL['bass']
                elif i%4==2: n, v = bn3, VOL['bass']-6
                else: n, v = bn, VOL['bass']-8
                set_cell(pat, base+i, CH_BASS, note=n, inst=BASS, vol=v)
        elif style == 'driving':
            for i in range(0,16,2):
                n = bn if i%4==0 else bn3
                v = VOL['bass'] if i%4==0 else VOL['bass']-6
                set_cell(pat, base+i, CH_BASS, note=n, inst=BASS, vol=v)
        elif style == 'pedal':
            set_cell(pat, base+0, CH_BASS, note=bn, inst=BASS, vol=VOL['bass'])
            set_cell(pat, base+8, CH_BASS, note=bn, inst=BASS, vol=VOL['bass']-4)
        elif style == 'syncopated':
            set_cell(pat, base+0, CH_BASS, note=bn, inst=BASS, vol=VOL['bass'])
            set_cell(pat, base+6, CH_BASS, note=bn, inst=BASS, vol=VOL['bass']-6)
            set_cell(pat, base+8, CH_BASS, note=bn3, inst=BASS, vol=VOL['bass']-4)
            set_cell(pat, base+14, CH_BASS, note=bn, inst=BASS, vol=VOL['bass']-8)
        elif style == 'off':
            pass

# ============================================================
# ARP
# ============================================================
def place_arp(pat, start_bar, num_bars, style='up', gbar_offset=0):
    for b in range(num_bars):
        bar = start_bar+b
        gbar = gbar_offset+b
        chord = chord_for_bar(gbar)
        notes = CHORDS[chord]['notes']
        octv = CHORDS[chord]['octave']
        base = bar*16
        if style == 'up':
            seq = [(notes[0],octv),(notes[1],octv),(notes[2],octv),(notes[2],octv+1)]
        elif style == 'updown':
            seq = [(notes[0],octv),(notes[1],octv),(notes[2],octv),(notes[1],octv)]
        elif style == 'upup':
            seq = [(notes[0],octv),(notes[1],octv),(notes[2],octv),(notes[0],octv+1)]
        elif style == 'octave':
            seq = [(notes[0],octv),(notes[0],octv+1),(notes[1],octv+1),(notes[0],octv+1)]
        else: continue
        for i in range(16):
            n = seq[i%4]
            v = VOL['arp'] if i%4==0 else VOL['arp']-6
            set_cell(pat, base+i, CH_ARP, note=f'{n[0]}-{n[1]}', inst=ARP, vol=v)

# ============================================================
# PAD (sustained root or slow triad arp)
# ============================================================
def place_pad(pat, start_bar, num_bars, style='sustained', gbar_offset=0):
    for b in range(num_bars):
        bar = start_bar+b
        gbar = gbar_offset+b
        chord = chord_for_bar(gbar)
        notes = CHORDS[chord]['notes']
        octv = CHORDS[chord]['octave']
        base = bar*16
        if style == 'sustained':
            set_cell(pat, base+0, CH_PAD, note=f'{notes[0]}-{octv}', inst=PAD, vol=VOL['pad'])
            set_cell(pat, base+8, CH_PAD, note=f'{notes[1]}-{octv}', inst=PAD, vol=VOL['pad']-4)
        elif style == 'triad':
            for i in range(0,16,2):
                nidx = (i//2)%3
                set_cell(pat, base+i, CH_PAD, note=f'{notes[nidx]}-{octv}', inst=PAD, vol=VOL['pad']-4)
        elif style == 'low':
            # low pad an octave below
            set_cell(pat, base+0, CH_PAD, note=f'{notes[0]}-{octv-1}', inst=PAD, vol=VOL['pad'])
            set_cell(pat, base+8, CH_PAD, note=f'{notes[1]}-{octv-1}', inst=PAD, vol=VOL['pad']-4)

# ============================================================
# STABS
# ============================================================
def place_stabs(pat, start_bar, num_bars, style='offbeat', gbar_offset=0):
    for b in range(num_bars):
        bar = start_bar+b
        gbar = gbar_offset+b
        chord = chord_for_bar(gbar)
        notes = CHORDS[chord]['notes']
        octv = CHORDS[chord]['octave']
        base = bar*16
        if style == 'offbeat':
            for i in [2,6,10,14]:
                set_cell(pat, base+i, CH_STAB, note=f'{notes[1]}-{octv}', inst=STAB, vol=VOL['stab'])
        elif style == 'syncopated':
            for i in [2,7,10,14]:
                set_cell(pat, base+i, CH_STAB, note=f'{notes[0]}-{octv}', inst=STAB, vol=VOL['stab'])
        elif style == 'off':
            pass

# ============================================================
# LEAD
# ============================================================
def place_lead(pat, start_bar, num_bars, melody, gbar_offset=0):
    for b in range(num_bars):
        bar = start_bar+b
        base = bar*16
        m = melody[b] if b < len(melody) else []
        for entry in m:
            row_off, nm, vol = entry
            if nm is None:
                note_off(pat, base+row_off, CH_LEAD)
            else:
                set_cell(pat, base+row_off, CH_LEAD, note=nm, inst=LEAD, vol=vol)

print("Core functions defined.")
PYEOF
